<?php
// views/user/laporan/laporantahunan.php - FINAL GABUNG UKS.CSS
batasi_akses_role(['admin','petugas']);
$tahun=$_GET['tahun']??date('Y');
$q=mysqli_query($koneksi,"SELECT MONTH(tanggalpenanganan) as bln, COUNT(*) as jml, SUM(CASE WHEN statuspasien='sembuh' THEN 1 ELSE 0 END) as sembuh, SUM(CASE WHEN statuspasien='rujuk' THEN 1 ELSE 0 END) as rujuk FROM penanganan WHERE YEAR(tanggalpenanganan)='$tahun' GROUP BY MONTH(tanggalpenanganan) ORDER BY bln ASC");
$detail=mysqli_query($koneksi,"SELECT p.*, s.namasiswa, g.namaguru FROM penanganan p LEFT JOIN siswa s ON p.idsiswa=s.idsiswa LEFT JOIN guru g ON p.idguru=g.idguru WHERE YEAR(p.tanggalpenanganan)='$tahun' ORDER BY p.tanggalpenanganan DESC");
?>
<div class="dash">
  <div class="content-header"><div class="container-fluid"><div class="row mb-2 align-items-center">
    <div class="col-sm-6"><h1 class="m-0 font-weight-bold" style="color:var(--dark)"><i class="fas fa-chart-bar mr-2" style="color:var(--teal)"></i> Laporan Tahunan <?= $tahun ?></h1><small class="text-muted">UKS Digital - <b style="color:var(--teal)">Rekap Tahunan</b> | <span class="badge-mint">Tahun <?= $tahun ?></span></small></div>
    <div class="col-sm-6 text-right"><form method="GET" class="form-inline float-right"><input type="hidden" name="halaman" value="laporantahunan"><select name="tahun" class="form-control form-control-sm mr-2"><?php for($t=date('Y');$t>=2023;$t--) echo "<option value='$t' ".($tahun==$t?'selected':'').">$t</option>"; ?></select><button class="btn-toska" style="padding:6px 16px; font-size:12px">Tampilkan</button> <a href="index.php?halaman=cetaklaporantahunan&tahun=<?= $tahun ?>" target="_blank" class="btn-cetak ml-1"><i class="fas fa-print mr-1"></i> Cetak</a></form></div>
  </div></div></div>
  <div class="content"><div class="container-fluid"><div class="row">
    <div class="col-md-4"><div class="uk-card-lap stat-lap"><div class="header-lap"><h6 class="font-weight-bold mb-0" style="color:var(--dark)">Rekap Per Bulan</h6></div><div class="table-responsive"><table class="table table-sm table-lap mb-0"><thead><tr><th>Bulan</th><th>Total</th><th>Sembuh</th><th>Rujuk</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($q)): ?><tr><td><?= date('F',mktime(0,0,0,$r['bln'],1)) ?></td><td><b><?= $r['jml'] ?></b></td><td><span class="badge-sembuh"><?= $r['sembuh'] ?></span></td><td><span class="badge-rujuk"><?= $r['rujuk'] ?></span></td></tr><?php endwhile; ?></tbody></table></div></div></div>
    <div class="col-md-8"><div class="uk-card-lap"><div class="header-lap"><h6 class="font-weight-bold mb-0" style="color:var(--dark)">Detail Kunjungan <?= $tahun ?></h6><span class="badge-mint"><?= mysqli_num_rows($detail) ?> Kunjungan</span></div><div class="table-responsive"><table class="table table-hover table-lap"><thead><tr><th>Tgl</th><th>Pasien</th><th>Keluhan</th><th>Status</th></tr></thead><tbody><?php while($d=mysqli_fetch_assoc($detail)): ?><tr><td><small><?= $d['tanggalpenanganan'] ?></small></td><td><b style="color:var(--dark)"><?= $d['namasiswa']?:$d['namaguru'] ?></b></td><td><small><?= $d['keluhan'] ?></small></td><td><span class="badge-<?= $d['statuspasien']=='sembuh'?'sembuh':($d['statuspasien']=='rujuk'?'rujuk':'istirahat') ?>"><?= $d['statuspasien'] ?></span></td></tr><?php endwhile; ?></tbody></table></div></div></div>
  </div></div></div>
</div>